// --- Rest with leading regular parameters ---
function clampAll(lo: number, hi: number, ...vals: number[]): number[] {
    let result = new Array<number>(vals.length)
    for (let i = 0; i < vals.length; i++) {
        let v: number = vals[i]
        result[i] = v < lo ? lo : v > hi ? hi : v
    }
    return result
}
