async/async_generator.code:
async function slowSquare(n: number): Promise<number> {
  return n * n
}

// Yields the running squares 1, 4, 9, 16, awaiting each computation.
async function* squares(limit: number): number {
  let i: number = 1
  while (i <= limit) {
    yield await slowSquare(i)
    i = i + 1
  }
}

// A throwing async generator rejects the outstanding .next() promise.
async function* boom(): number {
  yield 1
  throw new Error("stop")
}

// An async generator can yield objects (or tuples), and `for await...of` can
// destructure each yielded element straight into its own bindings.
async function* points(): { x: number; y: number } {
  yield { x: 1, y: 2 }
  yield { x: 3, y: 4 }
}

async function main(): Promise<void> {
  for await (const sq of squares(4)) {
    console.log(sq)          // 1, 4, 9, 16
  }

  // Destructuring loop variable: bind x and y from each yielded point.
  for await (const { x, y } of points()) {
    console.log(x + y)       // 3, 7
  }

  // Manual iteration: .next() returns a Promise<{value, done}>.
  const it = squares(1)
  const first = await it.next()
  console.log(first.value + " done=" + first.done)   // 1 done=false
  const end = await it.next()
  console.log("done=" + end.done)                      // done=true

  // .next() returns a genuinely-pending promise: the generator body runs as a
  // microtask, not synchronously at the .next() call. So a side effect before the
  // first yield is deferred past the code right after .next() — matching JS's
  // "before, after, body" ordering (ADR-00275).
  const d = deferredGen()
  console.log("before")                                // before
  const dp = d.next()
  console.log("after")                                 // after
  console.log((await dp).value)                        // body (from the gen), then 1

  const b = boom()
  console.log((await b.next()).value)                  // 1
  try {
    await b.next()
  } catch (e) {
    console.log("caught " + e.message)                 // caught stop
  }

  // .throw(e) injects an error at the suspension point; a body try/catch handles
  // it (and may await), so the .throw() promise fulfils with the recovered value.
  const g = guardedGen()
  console.log((await g.next()).value)                  // 1
  console.log((await g.throw(new Error("oops"))).value) // 42 (resumed in catch)

  // .return(v) completes an async generator early, running its finally block.
  const c = cleanupGen()
  console.log((await c.next()).value)                  // 1
  const r = await c.return(7)
  console.log(r.value + " done=" + r.done)             // 7 done=true

  // yield* delegates to an inner async generator: each inner step is awaited,
  // its values re-yielded, and its return value becomes the yield* result.
  for await (const v of composed()) {
    console.log(v)                                     // 1, 4, then 0
  }
}

async function* firstTwoSquares(): number {
  yield await slowSquare(1)                            // 1
  yield await slowSquare(2)                            // 4
  return 2                                             // count produced
}

async function* composed(): number {
  const count = yield* firstTwoSquares()
  console.log("delegated " + count + " values")        // delegated 2 values
  yield 0
}

async function* guardedGen(): number {
  try {
    yield await slowSquare(1)
    yield await slowSquare(2)
  } catch (e) {
    console.log("gen caught " + e.message)             // gen caught oops
    yield 42
  }
}

async function* cleanupGen(): number {
  try {
    yield 1
    yield 2
  } finally {
    console.log("gen cleanup")                         // runs on .return()
  }
}

// A side effect before the first yield: with a deferred .next(), it prints only
// once the microtask step runs — after "before"/"after" (see main()).
async function* deferredGen(): number {
  console.log("body")
  yield 1
}

main()

async/async_iterable.code:
// A separate iterator object: Range hands out a fresh RangeIter each iteration.
class RangeIter {
  private cur: number
  private end: number
  constructor(end: number) { this.cur = 0; this.end = end }
  async next(): Promise<{ value: number; done: boolean }> {
    if (this.cur >= this.end) { return { value: 0, done: true } }
    const v = this.cur
    this.cur = this.cur + 1
    return { value: v, done: false }
  }
}

class Range {
  private end: number
  constructor(end: number) { this.end = end }
  [Symbol.asyncIterator](): RangeIter { return new RangeIter(this.end) }
}

// A self-iterator (`return this`) whose next() awaits between elements.
async function fetchTick(n: number): Promise<number> {
  return n * 100
}

class Ticker {
  private i: number
  private n: number
  constructor(n: number) { this.i = 0; this.n = n }
  [Symbol.asyncIterator](): Ticker { return this }
  async next(): Promise<{ value: number; done: boolean }> {
    if (this.i >= this.n) { return { value: -1, done: true } }
    const t = await fetchTick(this.i)
    this.i = this.i + 1
    return { value: t, done: false }
  }
}

// The yielded value can be an object; the loop variable destructures it.
class PairIter {
  private i: number
  constructor() { this.i = 0 }
  [Symbol.asyncIterator](): PairIter { return this }
  async next(): Promise<{ value: { a: number; b: number }; done: boolean }> {
    if (this.i >= 3) { return { value: { a: 0, b: 0 }, done: true } }
    const j = this.i
    this.i = this.i + 1
    return { value: { a: j, b: j * j }, done: false }
  }
}

// An iterator whose next() throws rejects the awaited step, catchable normally.
class Boom {
  [Symbol.asyncIterator](): Boom { return this }
  async next(): Promise<{ value: number; done: boolean }> {
    throw new Error("stream failed")
  }
}

async function main(): Promise<void> {
  for await (const x of new Range(4)) {
    console.log(x)                      // 0, 1, 2, 3
  }

  for await (const t of new Ticker(3)) {
    console.log(t)                      // 0, 100, 200
  }

  for await (const { a, b } of new PairIter()) {
    console.log(a + " -> " + b)         // 0 -> 0, 1 -> 1, 2 -> 4
  }

  try {
    for await (const v of new Boom()) {
      console.log(v)
    }
  } catch (e) {
    console.log("caught " + e.message)  // caught stream failed
  }

  // for await also works over a sync array — each element is awaited, so an
  // array of promises is consumed sequentially (TDD-00092).
  const jobs: Promise<number>[] = [fetchTick(1), fetchTick(2), fetchTick(3)]
  for await (const n of jobs) {
    console.log("job " + n)             // job 100, job 200, job 300
  }
}

main()

async/concurrent_tasks.code:
async function fetchStatus(url: string): Promise<number> {
    const r = await fetch(url)
    return r.status
}

// ── Composition concurrency: both fetches are in flight before either await ──
const p1 = fetchStatus('http://127.0.0.1:8765/get')
const p2 = fetchStatus('http://127.0.0.1:8765/status/404')
console.log(await p1)   // 200
console.log(await p2)   // 404

// ── Promise.all over task promises: real concurrency, results in order ───────
const all: number[] = await Promise.all([
    fetchStatus('http://127.0.0.1:8765/get'),
    fetchStatus('http://127.0.0.1:8765/status/404'),
    fetchStatus('http://127.0.0.1:8765/get')
])
console.log(all[0] + ' ' + all[1] + ' ' + all[2])   // 200 404 200

// ── Promise.race / .any: the first member to settle wins ─────────────────────
// The slow one (delay/1) is listed first, so a fast result proves a real race.
const winner: number = await Promise.race([
    fetchStatus('http://127.0.0.1:8765/delay/1'),
    fetchStatus('http://127.0.0.1:8765/get')
])
console.log(winner)   // 200 — the fast one

const firstOk: number = await Promise.any([
    fetchStatus('http://127.0.0.1:8765/delay/1'),
    fetchStatus('http://127.0.0.1:8765/get')
])
console.log(firstOk)   // 200

// ── Promise.any over *raw* fetches (TDD-00084 Part C) ────────────────────────
// The array holds fetch() promises directly (not wrapped in an async fn). An
// unreachable host fails at the transport level and is skipped; the reachable
// one wins. If every fetch failed at the transport level, .any would throw an
// AggregateError whose .errors holds one Error per failed fetch.
const anyResp: Response = await Promise.any([
    fetch('http://127.0.0.1:1/unreachable'),
    fetch('http://127.0.0.1:8765/get')
])
console.log(anyResp.status)   // 200

// ── A nullable-scalar parameter in a genuinely-suspending fn (Part C) ────────
async function statusOr(url: string, fallback: number | null): Promise<number> {
    const r = await fetch(url)
    return r.ok ? r.status : (fallback ?? -1)
}
console.log(await statusOr('http://127.0.0.1:8765/get', null))        // 200
console.log(await statusOr('http://127.0.0.1:8765/status/404', 999)) // 999

async/for_await_iterables.code:
// A sync generator in `for await` (the spec's CreateAsyncFromSyncIterator):
// plain yields are identity-awaited, promise yields await to their values.
function* nums(): number {
  yield 1;
  yield 2;
  yield 3;
}
async function work(n: number): Promise<number> {
  return n * 10;
}
function* jobs(): Promise<number> {
  yield work(1);
  yield work(2);
}

// A class implementing the *sync* iteration protocol by hand —
// `[Symbol.iterator]()` returning an iterator whose `next()` yields the
// spec's `{value, done}` shape. Works in plain `for...of` too.
class Countdown {
  n: number;
  constructor(start: number) { this.n = start; }
  [Symbol.iterator](): Countdown { return this; }
  next(): { value: number; done: boolean } {
    if (this.n <= 0) { return { value: 0, done: true }; }
    const v = this.n;
    this.n = this.n - 1;
    return { value: v, done: false };
  }
}

async function* agen(): number {
  yield await work(4);
  yield await work(5);
}

async function main(): Promise<void> {
  for await (const n of nums()) { console.log(n); }   // 1 2 3
  for await (const v of jobs()) { console.log(v); }   // 10 20

  // Map values / Set elements, same shapes as sync for-of.
  const m = new Map<string, number>();
  m.set("a", 5);
  m.set("b", 7);
  for await (const v of m) { console.log(v); }        // 5 7
  const s = new Set<string>();
  s.add("hi");
  s.add("yo");
  for await (const t of s) { console.log(t); }        // hi yo

  // An object literal with a [Symbol.asyncIterator] member — arrow-valued or
  // method shorthand — is a for-await iterable.
  const obj = { [Symbol.asyncIterator]: () => agen() };
  for await (const x of obj) { console.log(x); }      // 40 50

  for (const x of new Countdown(3)) { console.log(x); }       // 3 2 1
  for await (const x of new Countdown(2)) { console.log(x); } // 2 1
}
main();

async/new_promise.code:
async function main(): Promise<void> {
  // Synchronous resolve.
  const answer = await new Promise<number>((resolve) => {
    resolve(42)
  })
  console.log(answer)                              // 42

  // Reject → await re-throws into a surrounding try/catch.
  try {
    await new Promise<number>((resolve, reject) => {
      reject(new Error("denied"))
    })
  } catch (e) {
    console.log("caught " + e.message)             // caught denied
  }

  // First settle wins: the later resolve and the reject are ignored.
  const once = await new Promise<number>((resolve, reject) => {
    resolve(1)
    resolve(2)
    reject(new Error("too late"))
  })
  console.log(once)                                // 1

  // The canonical use: wrap a callback/timer API. `resolve` is captured into the
  // setTimeout callback and called when the timer fires; awaiting drives it.
  console.log("waiting...")
  const delayed = await new Promise<string>((resolve) => {
    setTimeout(() => { resolve("done") }, 20)
  })
  console.log(delayed)                             // done

  // A chain on a new Promise runs its callback as a microtask.
  new Promise<number>((resolve) => resolve(10))
    .then((n: number) => n * 2)
    .then((m: number) => { console.log("chained " + m) })  // chained 20

  // Thenable adoption: resolving with a promise makes the outer promise mirror
  // it — the outer settles with the inner's value (or reason) when it settles.
  const adopted = await new Promise<number>((resolve) => {
    resolve(fetchAnswer())                         // resolve(aPromise)
  })
  console.log("adopted " + adopted)                // adopted 7
}

async function fetchAnswer(): Promise<number> {
  return 7
}
main()

