import http from 'http'

interface Res {
  status: number
  body: string
  bodyBytes: ArrayBuffer
}

setTimeout(() => {
  console.log('shutting down')
  process.exit(0)
}, 300)

console.log('listening on :8081')

http.listen(8081, (req: HttpRequest): Res => {
  // .bodyBytes() exposes the exact byte range the server already buffered
  // (Content-Length-aware, ADR-00072) — .byteLength reflects the real
  // count even when the body contains an embedded null.
  let buf: ArrayBuffer = req.bodyBytes()
  console.log('received ' + buf.byteLength + ' byte(s)')

  // body is still required (this compiler has no optional object fields),
  // but is ignored on the wire once bodyBytes is non-null.
  return { status: 200, body: '', bodyBytes: buf }
})

http/http_close.code:
import http from 'http'

interface Res {
  status: number
  body: string
}

let requestCount = 0

setTimeout(() => {
  console.log('auto-closing after demo delay')
  http.close()
}, 300)

console.log('listening on :8081')

http.listen(8081, (req: HttpRequest): Res => {
  requestCount = requestCount + 1
  if (req.path === '/shutdown') {
    http.close()
    return { status: 200, body: 'shutting down after ' + requestCount + ' request(s)' }
  }
  if (req.path === '/drain') {
    // Forceful shutdown: stop accepting, then drop every in-flight connection.
    // closeAllConnections() shuts down this request's own socket too, so the
    // returned response below won't reach the client — the caller sees the
    // connection close instead. That's the forceful contract (Node parity).
    http.close()
    http.closeAllConnections()
    return { status: 200, body: 'draining all connections' }
  }
  return { status: 200, body: 'hello (' + req.method + ' ' + req.path + ')' }
})

console.log('server closed, exiting')

