inspect/object_print.code:
class Point {
  x: number = 1;
  y: number = 2;
}
console.log(new Point()); // Point { x: 1, y: 2 }

class Person {
  name: string = "Ada";
  age: number = 36;
  admin: boolean = true;
}
console.log(new Person()); // Person { name: 'Ada', age: 36, admin: true }

// Object literals print without a name; empty objects show just the braces.
console.log({ id: 7, tag: "widget" }); // { id: 7, tag: 'widget' }
console.log({ outer: 1, inner: { x: 2, y: "deep" } }); // nested, recursed

// A bigint field shows the `n` suffix, like Node inspect.
class Money {
  amount: bigint = 1000n;
}
console.log(new Money()); // Money { amount: 1000n }

// Arrays render Node-style too (and console.log(array) now works at all).
console.log([1, 2, 3]); // [ 1, 2, 3 ]
console.log(["a", "b"]); // [ 'a', 'b' ]
console.log({ tags: [10, 20], owner: "me" }); // { tags: [ 10, 20 ], owner: 'me' }

// String coercion (default -compat=strict) uses the same useful view — never
// the information-losing [object Object] (that's opt-in via -compat=js).
const p = new Point();
console.log(`point = ${p}`); // point = Point { x: 1, y: 2 }

// A user-defined toString() is honored in string coercion (both modes); a bare
// console.log still shows the structured view, like Node.
class Price {
  amount: number = 42;
  toString(): string {
    return "$" + this.amount;
  }
}
const pr = new Price();
console.log(`price = ${pr}`); // price = $42
console.log(pr); // Price { amount: 42 }

interfaces/interfaces.code:
interface Point {
  x: number;
  y: number;
}

interface User {
  name: string;
  age: number;
}

// type alias — same power, different syntax
type Rect = { width: number; height: number }

function distance(p: Point): number {
  return Math.floor(Math.sqrt(p.x * p.x + p.y * p.y))
}

function greet(u: User): string {
  return `Hello ${u.name}, age ${u.age}`
}

function area(r: Rect): number {
  return r.width * r.height
}

const p: Point = { x: 3, y: 4 }
console.log(distance(p))     // 5

const u: User = { name: 'Alice', age: 30 }
console.log(greet(u))        // Hello Alice, age 30
console.log(JSON.stringify(u)) // {"name":"Alice","age":30}

const r: Rect = { width: 6, height: 7 }
console.log(area(r))         // 42

// Inline interface type in var decl
const p2: Point = { x: 0, y: 0 }
p2.x = 5
p2.y = 12
console.log(distance(p2))    // 13

// Interface fields default to i64 for `number` — a JSDoc @type comment
// overrides that per field, the same convention variable declarations
// already use (see jsdoc/ for the parser).
interface Measurement {
  label: string;
  /** @type {float64} */
  score: number;
}
const m: Measurement = { label: 'test', score: 9.5 }
console.log(m.score)               // 9.5
console.log(JSON.stringify(m))     // {"label":"test","score":9.5}

const parsed: Measurement = JSON.parse('{"label":"parsed","score":3.25}')
console.log(parsed.label)          // parsed
console.log(parsed.score)          // 3.25

// Array-typed fields carry their own length alongside the data, same as
// any other array value — .length, indexing, and for...of all just work.
interface Container {
  items: number[];
  label: string;
}
const initial: number[] = [10, 20, 30]
const c: Container = { items: initial, label: 'orig' }
console.log(c.items.length)        // 3
console.log(c.items[1])            // 20
for (const x of c.items) {
  console.log(x)                   // 10, 20, 30
}

const c2 = { ...c, label: 'copy' }
console.log(c2.items.length)       // 3

const { items: destructured } = c
destructured.push(40)
console.log(destructured.length)   // 4
console.log(c.items.length)        // 3 — destructuring copies, not aliases

function firstItems(cc: Container): number[] {
  return cc.items
}
console.log(firstItems(c).length)  // 3

json/json_methods.code:
// ── stringify numbers ─────────────────────────────────────────────────────────
const n: number = 42
console.log(JSON.stringify(n))       // 42

const neg: number = -7
console.log(JSON.stringify(neg))     // -7

// ── stringify strings ─────────────────────────────────────────────────────────
const s: string = 'hello'
console.log(JSON.stringify(s))       // 'hello'

const esc: string = "say 'hi'"
console.log(JSON.stringify(esc))     // 'say \"hi\"'

// ── stringify booleans ────────────────────────────────────────────────────────
console.log(JSON.stringify(true))    // true
console.log(JSON.stringify(false))   // false

// ── stringify number arrays ───────────────────────────────────────────────────
const nums: number[] = [1, 2, 3]
console.log(JSON.stringify(nums))    // [1,2,3]

const empty: number[] = []
console.log(JSON.stringify(empty))   // []

// ── stringify string arrays ───────────────────────────────────────────────────
const words: string[] = ['foo', 'bar', 'baz']
console.log(JSON.stringify(words))   // ['foo','bar','baz']

// ── stringify boolean arrays ──────────────────────────────────────────────────
const flags: boolean[] = [true, false, true]
console.log(JSON.stringify(flags))   // [true,false,true]

// ── stringify object arrays ───────────────────────────────────────────────────
interface Point { x: number; y: number }
const points: Point[] = [{ x: 1, y: 2 }, { x: 3, y: 4 }]
console.log(JSON.stringify(points))  // [{"x":1,"y":2},{"x":3,"y":4}]

// ── stringify pretty-printed (the `space` argument) ───────────────────────────
interface Addr { city: string; zip: number }
interface User { name: string; active: boolean; addr: Addr; tags: string[] }
const user: User = { name: 'bob', active: true, addr: { city: 'Thessaloniki', zip: 54600 }, tags: ['a', 'b'] }

// A numeric space indents with N spaces and puts a space after each colon.
console.log(JSON.stringify(user, null, 2))
// {
//   "name": "bob",
//   "active": true,
//   "addr": {
//     "city": "Thessaloniki",
//     "zip": 54600
//   },
//   "tags": [
//     "a",
//     "b"
//   ]
// }

// A string space is used literally as the indent unit (here a tab).
console.log(JSON.stringify({ x: 1, y: [1, 2] }, null, '\t'))

// Empty containers stay inline even when pretty-printing.
console.log(JSON.stringify({ e: {}, arr: [] }, null, 2))  // { "e": {}, "arr": [] } across lines

// ── stringify with a custom toJSON() ──────────────────────────────────────────
// If a class defines toJSON(), JSON.stringify serializes its result instead of
// the object's own fields — exactly as in real JS.
class Money {
  amount: number = 42
  currency: string = 'EUR'
  toJSON(): string { return this.amount + this.currency }
}
console.log(JSON.stringify(new Money()))              // "42EUR"
console.log(JSON.stringify({ price: new Money() }))   // {"price":"42EUR"}

// ── parse number ──────────────────────────────────────────────────────────────
const parsed: number = JSON.parse('123')
console.log(parsed)                  // 123

const neg2: number = JSON.parse('-99')
console.log(neg2)                    // -99

// ── parse string ──────────────────────────────────────────────────────────────
const str: string = JSON.parse('"world"')
console.log(str)                     // world

// ── malformed JSON throws a catchable SyntaxError (strict, like real JS) ───────
try {
  const bad: number = JSON.parse("{oops}")
  console.log(bad)
} catch (e) {
  console.log(e.name)                // SyntaxError
}

// ── round-trip ────────────────────────────────────────────────────────────────
const orig: number = 999
const serialized: string = JSON.stringify(orig)
const restored: number = JSON.parse(serialized)
console.log(restored)               // 999

const origStr: string = 'TypeGo'
const serializedStr: string = JSON.stringify(origStr)
const restoredStr: string = JSON.parse(serializedStr)
console.log(restoredStr)            // TypeGo

// ── parse object (flat objects, primitive fields only — nested object ──────────
// ── fields are not yet supported) ───────────────────────────────────────────────
interface Coord { x: number; y: number }
const coord: Coord = JSON.parse('{"x":10,"y":20}')
console.log(coord.x)                // 10
console.log(coord.y)                // 20

interface Account { name: string; balance: number; active: boolean }
const account: Account = JSON.parse('{"name":"Alice","balance":100,"active":true}')
console.log(account.name)           // Alice
console.log(account.balance)        // 100
console.log(account.active)         // 1

// A missing key falls back to the field type's zero value.
interface Pair { a: number; b: number }
const pair: Pair = JSON.parse('{"a":5}')
console.log(pair.a)                 // 5
console.log(pair.b)                 // 0

// ── parse nested objects, array fields, and top-level arrays ──────────────────
// (Addr is declared above, in the pretty-printing section.)
interface Member { name: string; addr: Addr; tags: string[] }
const m: Member = JSON.parse('{"name":"Nikos","addr":{"city":"Thessaloniki","zip":54600},"tags":["admin","dev"]}')
console.log(m.addr.city)            // Thessaloniki  (nested object field)
console.log(m.tags[1])              // dev           (array-typed field)

// a top-level array of objects
const members: Member[] = JSON.parse('[{"name":"A","addr":{"city":"X","zip":1},"tags":[]},{"name":"B","addr":{"city":"Y","zip":2},"tags":["x"]}]')
console.log(members.length)         // 2
console.log(members[1].addr.city)  // Y

