language/spread_args.code:
function sum(...nums: number[]): number {
  let total = 0;
  for (const n of nums) total += n;
  return total;
}

const values = [4, 8, 15, 16, 23, 42];
console.log("sum of all:", sum(...values));
console.log("sum of some:", sum(1, 2, 3));

// A spread may follow fixed arguments.
function tagged(tag: string, ...nums: number[]): string {
  return tag + " (" + nums.length + " values, sum " + sum(...nums) + ")";
}
console.log(tagged("data", ...values));

// Arrow functions with a rest parameter work the same way.
const product = (...nums: number[]): number => {
  let p = 1;
  for (const n of nums) p *= n;
  return p;
};
console.log("product:", product(...[2, 3, 4]));

// Multiple spreads and positional arguments freely mix, concatenating into the
// rest parameter at runtime in left-to-right order.
const lows = [1, 2, 3];
const highs = [100, 200];
console.log("merged sum:", sum(...lows, 50, ...highs));

// Spread into a class method's rest parameter, instance or static.
class Stats {
  totalFrom(base: number, ...nums: number[]): number {
    let t = base;
    for (const n of nums) t += n;
    return t;
  }
  static sum(...nums: number[]): number {
    let t = 0;
    for (const n of nums) t += n;
    return t;
  }
}
const stats = new Stats();
console.log("total from base:", stats.totalFrom(1000, ...lows, ...highs));
console.log("static sum:", Stats.sum(...lows, ...highs));

// Spread also works into the common variadic builtins, folded at runtime.
console.log("largest:", Math.max(...lows, ...highs));
console.log("smallest:", Math.min(0, ...lows));
console.log("all values:", ...lows, ...highs);

literal_expressions/literal_expressions.code:
// --- Array literal as a call argument ---

function first(arr: number[]): number {
  return arr[0];
}
console.log(first([10, 20, 30]));  // 10

// The declared parameter type drives coercion, not just the literal's own
// self-inferred type — [1, 2] here is built as float64[], not int64[].
function sum(arr: float64[]): float64 {
  return arr[0] + arr[1];
}
console.log(sum([1, 2]));  // 3

// --- Array literal as a return value ---

function pair(): number[] {
  return [1, 2];
}
const p = pair();
console.log(p[0]);       // 1
console.log(p.length);   // 2

// --- Array literal as an object-literal field value ---

interface Box {
  data: number[];
}
const box: Box = { data: [5, 6, 7] };
console.log(box.data[0]);       // 5
console.log(box.data.length);   // 3

// --- Plain reassignment (no let/const — was previously rejected outright) ---

let arr: number[] = [1, 2, 3];
arr = [4, 5];
console.log(arr[0]);       // 4
console.log(arr.length);   // 2

const other: number[] = [7, 8, 9];
arr = other;
console.log(arr[0]);       // 7

// --- Spread-containing literal as a call argument ---

const base: number[] = [1, 2];
console.log(first([...base, 3, 4]));  // 1
console.log(first([0, ...base]));     // 0

// --- new Array<T>(n) as a call argument ---

function len(a: number[]): number {
  return a.length;
}
console.log(len(new Array<number>(5)));  // 5

// --- new Map/Set/EventEmitter as a call argument or return value ---

function firstValue(m: Map<string, number>): number {
  return m.get("a");
}
const built = new Map<string, number>();
built.set("a", 42);
console.log(firstValue(built));  // 42

function makeMap(): Map<string, number> {
  return new Map<string, number>();
}
const m = makeMap();
m.set("x", 7);
console.log(m.get("x"));  // 7

function makeSet(): Set<number> {
  return new Set<number>();
}
const s = makeSet();
s.add(9);
console.log(s.has(9));  // 1

function makeEmitter(): EventEmitter<string> {
  return new EventEmitter<string>();
}
const e = makeEmitter();
e.on("msg", (data: string): void => {
  console.log("got: " + data);  // got: hi
});
e.emit("msg", "hi");

// Nested array literals (array-of-arrays) are a separate, still-open gap —
// see docs/tdd/TDD-00029.md — deliberately not demonstrated here.

map/map.code:
const scores = new Map<string, number>();

scores.set("alice", 95);
scores.set("bob", 87);
scores.set("carol", 92);

console.log(scores.size);         // 3
console.log(scores.get("alice")); // 95
console.log(scores.has("bob"));   // 1
console.log(scores.has("dave"));  // 0

scores.delete("bob");
console.log(scores.size);         // 2

// Number-keyed map
const lookup = new Map<number, number>();
lookup.set(1, 100);
lookup.set(2, 200);
lookup.set(3, 300);

console.log(lookup.get(2));  // 200
console.log(lookup.has(4));  // 0

// ── for...of iterates a Map's values (this compiler has no [key,value] ─────
// destructuring in for-of, so use .keys() for keys) ─────────────────────────
for (const v of lookup) {
  console.log(v);
}
// 100
// 200
// 300

for (const k of scores.keys()) {
  console.log(k);
}
// alice
// carol

// ── .forEach(fn): calls fn(value, key) for each entry ───────────────────────
scores.forEach((v, k) => {
  console.log(k + " -> " + v);
});
// alice -> 95
// carol -> 92

// ── .entries(): a real [key, value] tuple — destructure it directly ─────────
for (const [key, value] of lookup.entries()) {
  console.log(key + " = " + value);
}
// 1 = 100
// 2 = 200
// 3 = 300

// ── .clear(): removes every entry, size drops to 0, map stays usable ────────
console.log(scores.size); // 2
scores.clear();
console.log(scores.size); // 0
console.log(scores.has("alice")); // 0
scores.set("dave", 100);
console.log(scores.size); // 1

// ── new Map(entries): seed a map from a [key, value][] array of 2-tuples ─────
// K/V are inferred from the entries when no <K, V> is given (here string/number)
const prices = new Map([["pen", 2], ["notebook", 5], ["eraser", 1]]);
console.log(prices.get("notebook")); // 5
console.log(prices.size);            // 3

// An explicit <K, V> wins over inference
const codes = new Map<number, string>([[404, "Not Found"], [200, "OK"]]);
console.log(codes.get(200)); // OK

// The entries source can be an already-declared [K, V][] variable
const pairs: [string, number][] = [["x", 10], ["y", 20]];
const coords = new Map(pairs);
console.log(coords.get("y")); // 20

math/math_methods.code:
// ── constants ─────────────────────────────────────────────────────────────────
console.log(Math.PI)     // 3.141592653589793
console.log(Math.E)      // 2.718281828459045
console.log(Math.SQRT2)  // 1.4142135623730951

// ── floor / ceil / round / trunc ─────────────────────────────────────────────
console.log(Math.floor(3.7))   // 3
console.log(Math.floor(-3.2))  // -4
console.log(Math.ceil(3.2))    // 4
console.log(Math.ceil(-3.7))   // -3
console.log(Math.round(3.5))   // 4
console.log(Math.round(3.4))   // 3
console.log(Math.trunc(3.9))   // 3
console.log(Math.trunc(-3.9))  // -3

// floor on integer is a no-op
const n: number = 5
console.log(Math.floor(n))  // 5

// ── abs ───────────────────────────────────────────────────────────────────────
console.log(Math.abs(-10))   // 10
console.log(Math.abs(10))    // 10
console.log(Math.abs(0))     // 0

const fv: number = -3
console.log(Math.abs(fv))   // 3

// ── min / max ─────────────────────────────────────────────────────────────────
console.log(Math.min(3, 7))     // 3
console.log(Math.min(7, 3))     // 3
console.log(Math.max(3, 7))     // 7
console.log(Math.max(7, 3))     // 7
console.log(Math.min(1, 5, 3))  // 1
console.log(Math.max(1, 5, 3))  // 5

// ── sign ──────────────────────────────────────────────────────────────────────
console.log(Math.sign(42))   // 1
console.log(Math.sign(-7))   // -1
console.log(Math.sign(0))    // 0

// ── pow / sqrt ────────────────────────────────────────────────────────────────
console.log(Math.pow(2.0, 10.0))   // 1024
console.log(Math.sqrt(9.0))         // 3

// ── log ───────────────────────────────────────────────────────────────────────
console.log(Math.floor(Math.log2(8.0)))   // 3
console.log(Math.floor(Math.log10(1000.0))) // 3

// ── trig ──────────────────────────────────────────────────────────────────────
// sin(PI/2) ≈ 1.0
const sinHalf = Math.sin(Math.PI / 2.0)
console.log(Math.round(sinHalf))   // 1

// cos(0) = 1.0
const cosZero = Math.cos(0.0)
console.log(Math.round(cosZero))   // 1

// ── hypot ─────────────────────────────────────────────────────────────────────
console.log(Math.hypot(3.0, 4.0))  // 5

// ── inverse trig ──────────────────────────────────────────────────────────────
console.log(Math.round(Math.asin(1.0) * 2.0))  // 3 (asin(1) = PI/2, *2 ≈ PI ≈ 3.14 → rounds to 3)
console.log(Math.acos(1.0))                     // 0
console.log(Math.round(Math.atan(1.0) * 4.0))   // 3 (atan(1) = PI/4, *4 ≈ PI ≈ 3.14 → rounds to 3)
console.log(Math.round(Math.atan2(1.0, 1.0) * 4.0))  // 3

// ── hyperbolic ────────────────────────────────────────────────────────────────
console.log(Math.sinh(0.0))   // 0
console.log(Math.cosh(0.0))   // 1
console.log(Math.tanh(0.0))   // 0

// ── cbrt / expm1 / log1p ──────────────────────────────────────────────────────
console.log(Math.cbrt(27.0))   // 3
console.log(Math.expm1(0.0))   // 0
console.log(Math.log1p(0.0))   // 0

// ── clamp (TypeGo extension) ──────────────────────────────────────────────────
console.log(Math.clamp(5, 0, 10))   // 5
console.log(Math.clamp(-5, 0, 10))  // 0
console.log(Math.clamp(15, 0, 10))  // 10

// ── random ────────────────────────────────────────────────────────────────────
// Math.random() returns a float in [0, 1); just verify it's in range
const r = Math.random()
const inRange = r >= 0.0 && r < 1.0
console.log(inRange)  // 1

// Common pattern: random integer in [0, n)
const roll = Math.floor(Math.random() * 6.0)
const rollOk = roll >= 0 && roll < 6
console.log(rollOk)  // 1

// ── clz32 / imul / fround ──────────────────────────────────────────────────────
console.log(Math.clz32(1))           // 31
console.log(Math.clz32(0))           // 32
console.log(Math.imul(3, 4))         // 12
console.log(Math.imul(-5, 12))       // -60 (32-bit wraparound multiply)
console.log(Math.fround(5.5))        // 5.5 (exactly representable in float32)

memory/memory_free.code:
import Memory from 'memory'

// ── string (must be a dynamically-built one, not a literal) ─────────────────
let big: string = "hello " + "world"   // concatenation result -> malloc'd
console.log(big.length)   // 11
Memory.free(big)
console.log(big === null)  // true — the variable's own storage was nulled

// ── array ────────────────────────────────────────────────────────────────────
let nums: number[] = [1, 2, 3, 4, 5]
console.log(nums.length)   // 5
Memory.free(nums)
console.log(nums.length)   // 0 — nulled out, not a stale read

// ── object ───────────────────────────────────────────────────────────────────
interface Point { x: number; y: number }
let p: Point = { x: 1, y: 2 }
console.log(p.x)   // 1
Memory.free(p)

// ── closure ──────────────────────────────────────────────────────────────────
// Frees the closure's own header + environment struct. A captured
// variable's own heap-promoted cell (shared with the enclosing scope,
// ADR-00001) is deliberately left untouched — freeing it here could free
// memory the enclosing scope, or another closure, is still actively using.
let counter: number = 0
const inc = (): number => { counter = counter + 1; return counter }
console.log(inc())   // 1
console.log(inc())   // 2
Memory.free(inc)
console.log(counter)   // 2 — the shared cell survived the closure's own free

// ── Map / Set ────────────────────────────────────────────────────────────────
// Frees the map's own two backing buffers (keys array, values array) plus
// its header struct — not each individual key/value pair.
let scores: Map<string, number> = new Map<string, number>()
scores.set("alice", 10)
scores.set("bob", 20)
console.log(scores.size)   // 2
Memory.free(scores)

let tags: Set<string> = new Set<string>()
tags.add("greek")
console.log(tags.size)   // 1
Memory.free(tags)

// ── a directly-evaluated expression works too, not just named variables ────
function makePoint(): Point {
    return { x: 3, y: 4 }
}
Memory.free(makePoint())

// ── freeing the same named variable twice is harmless ───────────────────────
// (free(NULL) is a well-defined no-op in C — the first call already nulled
// the variable's storage.) Freeing the same allocation through two
// DIFFERENT aliases is still unsafe — this only covers the one-variable case.
