net/client_server.code:
import net from 'net';

// A self-contained TCP round trip: a server echoes one message, and a client
// connects to it, sends a line, prints the echo, then tears both down so the
// example terminates (a real client/server would live longer).
const dec = new TextDecoder();

const server = net.createServer((conn) => {
  conn.on('data', (chunk: Uint8Array) => {
    conn.write("echo:" + dec.decode(chunk));
  });
});

server.listen(9109, () => {
  const client = net.connect(9109, "127.0.0.1", () => {
    client.write("hello");
  });
  client.on('data', (chunk: Uint8Array) => {
    console.log("client received:", dec.decode(chunk));
    client.end();
    server.close();
  });
});

net/echo_server.code:
import net from 'net';

// A TCP echo server: every chunk received on a connection is written back.
// Self-terminates after a short delay so this example runs to completion
// (a real server would simply omit the timer and listen indefinitely).
const server = net.createServer((socket) => {
  socket.on('data', (chunk: Uint8Array) => {
    socket.write(chunk);
  });
  socket.on('end', () => {
    console.log('client disconnected');
  });
});

server.listen(9099, () => {
  console.log('TCP echo server listening on 9099');
});

setTimeout(() => {
  server.close();
  console.log('server closed');
}, 100);

