// An 8-bit unsigned integer wraps at its width, exactly like C / a typed array.
/** @type {uint8} */
let r = 255
r = r + 1
console.log(r)                    // 0  (wrapped at 8 bits)

// Single-precision float: narrower than the default IEEE-754 double.
