interface User {
	name: string
	age: number
}

// Partial<User>: every field is optional, so a literal may omit some.
const draft: Partial<User> = { name: "Zoe" }
console.log(draft.name)            // Zoe

// Required<User> / Readonly<User>: same shape as User here.
const full: Required<User> = { name: "Ada", age: 36 }
console.log(full.name + " is " + full.age)  // Ada is 36

const frozen: Readonly<User> = { name: "Kay", age: 40 }
console.log(frozen.age)            // 40

// A Partial as a function parameter — a common "options bag" pattern.
function describe(u: Partial<User>): string {
	return u.name + " (" + u.age + ")"
}
console.log(describe({ name: "Sam", age: 22 }))  // Sam (22)

// NonNullable<T> strips null/undefined from the type.
function must(x: NonNullable<string | null>): string {
	return x.toUpperCase()
}
console.log(must("ready"))         // READY

// --- Stage 1b: key-based utilities over a string-literal-union key ---

// Pick<T, K> keeps only the named fields; Omit<T, K> drops them.
const contact: Pick<User, "name"> = { name: "Ivy" }
console.log(contact.name)          // Ivy

const noAge: Omit<User, "age"> = { name: "Jo" }
console.log(noAge.name)            // Jo

// Record<K, V>: a literal-union key gives a fixed-shape object …
const grades: Record<"math" | "science", number> = { math: 90, science: 85 }
console.log(grades.math + grades.science)   // 175

// … and a general `string` key gives a Map<string, V>.
const counts: Record<string, number> = new Map()
counts.set("hits", 3)
console.log(counts.get("hits"))    // 3

// A string-literal union type is usable on its own (resolves to string).
type Direction = "north" | "south" | "east" | "west"
const heading: Direction = "north"
console.log(heading)               // north

url/url.code:
// ── parsing a URL into its parts ─────────────────────────────────────────────
const u = new URL("https://example.com:8080/a/b?x=1&y=hello%20world#frag")
console.log(u.href)      // https://example.com:8080/a/b?x=1&y=hello%20world#frag
console.log(u.protocol)  // https:
console.log(u.hostname)  // example.com
console.log(u.host)      // example.com:8080
console.log(u.port)      // 8080
console.log(u.pathname)  // /a/b
console.log(u.search)    // ?x=1&y=hello%20world
console.log(u.hash)      // #frag
console.log(u.origin)    // https://example.com:8080

// Parts that don't appear in the URL come back as an empty string, not
// undefined/null (this compiler has no optional-field concept for a plain
// object type) — matching real URL's own "" default for an absent part.
const bare = new URL("https://example.com/path")
console.log(bare.port)    // (empty)
console.log(bare.search)  // (empty)
console.log(bare.hash)    // (empty)

// A malformed URL throws a catchable Error rather than crashing.
try {
  new URL("not a url")
} catch (e) {
  console.log(e.message)  // Invalid URL
}

// ── searchParams: URL's own query string as a live URLSearchParams ──────────
console.log(u.searchParams.get("x"))       // 1
console.log(u.searchParams.get("y"))       // hello world (percent-decoded)
console.log(u.searchParams.has("z"))       // 0 (false — not present)
console.log(u.searchParams.get("z"))       // null

// ── URLSearchParams on its own, for building a query string ─────────────────
const params = new URLSearchParams()
params.set("q", "hello world")
params.set("page", "2")
console.log(params.toString())  // q=hello%20world&page=2

// Parsing an existing query string tolerates a leading '?' (so passing a
// URL's own .search straight through just works).
const parsed = new URLSearchParams(u.search)
console.log(parsed.get("x"))  // 1

// get/set/has/delete/size/keys()/values()/entries()/forEach() all come for
// free from the underlying Map<string,string> — no separate API surface.
console.log(parsed.size)
for (const key of parsed.keys()) {
  console.log(key)
}

url/urlpattern.code:
// ── route-style matching with named groups ───────────────────────────────────
const pattern = new URLPattern({ pathname: "/books/:id" })
console.log(pattern.pathname)                                  // /books/:id
console.log(pattern.protocol)                                  // * (defaulted)
console.log(pattern.test("https://example.com/books/123"))     // true
console.log(pattern.test("https://example.com/authors/9"))     // false

const m = pattern.exec("https://example.com/books/123")
if (m !== null) {
  console.log(m.get("id"))                                     // 123
}
console.log(pattern.exec("https://example.com/nope") === null) // true

// ── multiple components + an optional trailing segment ───────────────────────
const api = new URLPattern({
  protocol: "https",
  hostname: "api.example.com",
  pathname: "/v1/:resource/:id?",
})
console.log(api.test("https://api.example.com/v1/users/42"))   // true
console.log(api.test("https://api.example.com/v1/users"))      // true (optional :id?)
console.log(api.test("http://api.example.com/v1/users/42"))    // false (protocol)

const g = api.exec("https://api.example.com/v1/users/42")
if (g !== null) {
  console.log(g.get("resource"))                               // users
  console.log(g.get("id"))                                     // 42
}

// ── empty pattern means "must be empty"; no init matches everything ──────────
console.log(new URLPattern({ search: "" }).test("https://e.com/a?q=1")) // false
console.log(new URLPattern({ search: "" }).test("https://e.com/a"))     // true
console.log(new URLPattern().test("https://anything.example/x#f"))      // true

// ── an invalid pattern throws a catchable TypeError at construction ──────────
try {
  const bad = new URLPattern({ pathname: "/x/{group}" })
  console.log(bad.test("https://e.com/x/y"))
} catch (e) {
  console.log(e instanceof TypeError)                          // true
}

